package com.bookreads.api

import com.bookreads.dto.SessionSyncRequest
import com.bookreads.repository.SessionRepository
import com.bookreads.storage.LocalSessionStore
import com.bookreads.storage.SessionData
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

class SessionSyncService(
    private val sessionRepository: SessionRepository,
    private val localSessionStore: LocalSessionStore,
) {
    private var syncJob: Job? = null

    suspend fun syncSession(
        data: SessionData,
        username: String,
    ) {
        val request = SessionSyncRequest(
            clientId = data.clientId,
            username = username,
            bookTitle = data.bookTitle,
            startedAt = data.startedAt,
            endedAt = data.endedAt,
            durationSec = data.elapsedOffsetSec,
        )
        runCatching { sessionRepository.sync(request) }
        localSessionStore.saveActiveSession(data)
    }

    fun startPeriodicSync(
        scope: CoroutineScope,
        getData: () -> SessionData?,
        getUsername: () -> String,
    ) {
        syncJob?.cancel()
        syncJob = scope.launch {
            while (true) {
                delay(SYNC_INTERVAL_MS)
                val data = getData() ?: break
                syncSession(data, getUsername())
            }
        }
    }

    fun stopPeriodicSync() {
        syncJob?.cancel()
        syncJob = null
    }

    companion object {
        const val SYNC_INTERVAL_MS = 30_000L
    }
}
